import { usePageFilterApplied, usePageFilterData } from 'hooks';

import { INNOVATION_HUB_PAGE_NAME } from '../../../constants';

export function usePerformanceAndBreakdownFilters() {
  const { applied, isGlobalZone } = usePageFilterApplied(
    INNOVATION_HUB_PAGE_NAME,
  );
  const { dataFilters } = usePageFilterData(INNOVATION_HUB_PAGE_NAME);
  const kpi = applied?.kpis == null ? undefined : String(applied.kpis);

  return { applied, isGlobalZone, dataFilters, kpi };
}
